#define MT_IA           397
#define MT_IB           (MT_LEN - MT_IA)
#define UPPER_MASK      0x80000000
#define LOWER_MASK      0x7FFFFFFF
#define MATRIX_A        0x9908B0DF
#define TWIST(b,i,j)    ((b)[i] & UPPER_MASK) | ((b)[j] & LOWER_MASK)
#define MAGIC(s)        (((s)&1)*MATRIX_A)

uint32_t mt_random() {
    uint32_t *b = mt_buffer;
    int idx = mt_index;
    uint32_t s;
    int i;
    if (idx == MT_LEN*sizeof(uint32_t))
    {
        idx = 0;
        i = 0;
        for (; i < MT_IB; i++) {
            s = TWIST(b, i, i+1);
            b[i] = b[i + MT_IA] ^ (s >> 1) ^ MAGIC(s);
        }
        for (; i < MT_LEN-1; i++) {
            s = TWIST(b, i, i+1);
            b[i] = b[i - MT_IB] ^ (s >> 1) ^ MAGIC(s);
        }
        s = TWIST(b, MT_LEN-1, 0);
        b[MT_LEN-1] = b[MT_IA-1] ^ (s >> 1) ^ MAGIC(s);
    }
    mt_index = idx + sizeof(uint32_t);
    return *(uint32_t *)((unsigned char *)b + idx);
}

int main(int argc, char *argv[]) {

    FILE *outfile;
    char byte;

    if (argc == 3) {
        
        // process command line arguments
        outfile = fopen(argv[1], "wb");
        int n_bytes = atoi(argv[2]);

        // write random bytes to file
        for (int n = 0; n < n_bytes; n++) {
            byte = mt_random() & 0xff;
            fwrite(&byte, 1, sizeof(byte), outfile);
        }
        
        fclose(outfile);
    }
    else {
        printf("Usage: %s <output-file> <number-of-rng-bytes>\n", argv[0]);
    }
   
    return 0;
}

